'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const source=fs.readFileSync(path.join(__dirname,'app.js'),'utf8'),css=fs.readFileSync(path.join(__dirname,'style.css'),'utf8');
const start=source.indexOf('function nightMinutes('),end=source.indexOf('const defaults=',start);
assert.ok(start>=0&&end>start);
const {nightMinutes:m,normaliseNight:n,nightActive:a,displayDim:d,hardwareBrightness:h}=new Function(source.slice(start,end)+';return {nightMinutes,normaliseNight,nightActive,displayDim,hardwareBrightness};')();
assert.deepEqual(n(),{night:'off',nightStart:'22:00',nightEnd:'07:00',nightDim:55});
assert.deepEqual(n({night:'bad',nightStart:'25:01',nightEnd:'7:00',nightDim:90}),n());
assert.equal(m('00:00'),0);assert.equal(m('23:59'),1439);assert.equal(m('24:00'),null);assert.equal(m('09:60'),null);
const overnight={night:'scheduled',nightStart:'22:00',nightEnd:'07:00',nightDim:55,brightness:100};
for(const [minute,expected] of [[1319,false],[1320,true],[1439,true],[0,true],[419,true],[420,false],[720,false]])assert.equal(a(overnight,minute),expected);
const day={...overnight,nightStart:'08:00',nightEnd:'16:00'};
for(const [minute,expected] of [[479,false],[480,true],[959,true],[960,false]])assert.equal(a(day,minute),expected);
assert.equal(a({...overnight,nightStart:'07:00'},420),false);
assert.equal(a({...overnight,night:'manual'},720),true);
assert.equal(a({...overnight,night:'off'},0),false);
assert.equal(a(overnight,1440),false);
const near=(actual,expected)=>assert.ok(Math.abs(actual-expected)<1e-9);
near(d(overnight,0),.55);
near(d(overnight,720),0);
near(d({...overnight,brightness:20,nightDim:30},0),.6);
near(d({...overnight,brightness:60,nightDim:70},0),.7);
near(d({...overnight,brightness:60,night:'off'},0),.3);
assert.ok(source.includes('Object.assign(prefs,normaliseNight(p))'));
assert.ok(source.includes('clock();updateNightMode();'));
assert.ok(source.includes("document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateNightMode()})"));
assert.ok(source.includes('...normaliseNight(),spotifyBackground:'));
assert.ok(css.includes('pointer-events:none;z-index:8'));
assert.equal(h(overnight,0),45);
assert.equal(h(overnight,720),100);
assert.equal(h({...overnight,brightness:20,nightDim:30},0),20);
assert.equal(h({...overnight,brightness:60,nightDim:70},0),30);
assert.equal(h({...overnight,brightness:60,night:'off'},0),60);
assert.equal(h({brightness:0},0),10);
assert.equal(h({brightness:120},0),100);
assert.equal(h({brightness:NaN},0),100);
assert.ok(source.includes('nativeBrightness?0:displayDim'));
console.log('Night mode and hardware brightness regression checks passed');
